const allowed = {
  "application/pdf": "pdf",
  "image/jpeg": "image",
  "image/jpg": "image",
  "image/png": "image"
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const binary = item.binary || {};
  let from = "";
  if (typeof j.from === "string") { from = j.from; }
  else if (j.from && typeof j.from.text === "string") { from = j.from.text; }
  else if (j.headers && j.headers.from) { from = String(j.headers.from); }
  const keys = Object.keys(binary).filter(function (k) { return k.indexOf("attachment_") === 0; });
  for (const key of keys) {
    const b = binary[key];
    const mime = String(b.mimeType || "").toLowerCase().split(";")[0].trim();
    out.push({
      json: {
        file_name: b.fileName || key,
        mime_type: mime,
        file_kind: allowed[mime] || "unsupported",
        source_email: from,
        email_subject: j.subject || "",
        message_id: j.id || "",
        received_at: j.date || new Date().toISOString()
      },
      binary: { data: b }
    });
  }
}
return out;

const raw = $json;
function collectText(v) {
  if (v === null || v === undefined) { return ""; }
  if (typeof v === "string") { return v; }
  if (Array.isArray(v)) { return v.map(collectText).join("\n"); }
  if (typeof v === "object") {
    if (typeof v.text === "string") { return v.text; }
    if (v.parts !== undefined) { return collectText(v.parts); }
    if (v.content !== undefined) { return collectText(v.content); }
  }
  return "";
}
let text = "";
if (Array.isArray(raw.candidates)) { text = collectText(raw.candidates); }
else if (raw.content !== undefined) { text = collectText(raw.content); }
else if (typeof raw.text === "string") { text = raw.text; }
else if (typeof raw.response === "string") { text = raw.response; }

let cleaned = String(text).trim();
cleaned = cleaned.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
const start = cleaned.indexOf("{");
const end = cleaned.lastIndexOf("}");
if (start !== -1 && end !== -1 && end > start) { cleaned = cleaned.slice(start, end + 1); }

let src;
try { src = $("Split Attachments").item; } catch (e) { src = $("Split Attachments").first(); }
const meta = src.json || {};

let data = null;
let parseOk = true;
let parseError = "";
try { data = JSON.parse(cleaned); } catch (err) { parseOk = false; parseError = err.message; }
if (parseOk && (data === null || typeof data !== "object" || Array.isArray(data))) { parseOk = false; parseError = "model did not return a JSON object"; }
const d = data || {};

function num(v) {
  if (typeof v === "number") { return Number.isFinite(v) ? v : null; }
  if (v === null || v === undefined || v === "") { return null; }
  const cleanedNum = String(v).replace(/[^0-9.,-]/g, "").replace(/,(?=[0-9]{3}\b)/g, "").replace(",", ".");
  const n = parseFloat(cleanedNum);
  return Number.isFinite(n) ? n : null;
}
function safe(s) {
  return String(s === null || s === undefined || s === "" ? "unknown" : s).replace(/[\\/:*?"<>|]+/g, "-").replace(/\s+/g, " ").trim().slice(0, 60);
}

const subtotal = num(d.subtotal);
const taxAmount = num(d.tax_amount);
const totalAmount = num(d.total_amount);
const confidence = num(d.confidence_score);
const notes = [];
let mathOk = false;
// A receipt with no VAT line is legitimate, so a missing tax is zero rather than
// a missing figure. Treating it as missing flagged every tax-exempt receipt.
const taxForMath = taxAmount === null ? 0 : taxAmount;
if (subtotal !== null && totalAmount !== null) {
  const tolerance = Math.max(0.02, Math.abs(totalAmount) * 0.01);
  mathOk = Math.abs(subtotal + taxForMath - totalAmount) <= tolerance;
  if (!mathOk) { notes.push("subtotal + tax_amount does not equal total_amount"); }
  if (taxAmount === null) { notes.push("no tax line; treated as 0"); }
} else if (parseOk) {
  notes.push("missing subtotal or total_amount");
}
if (confidence === null) { notes.push("no confidence_score returned"); }
else if (confidence < 0.6) { notes.push("low confidence (" + confidence + ")"); }
if (!parseOk) { notes.push("JSON parse failed: " + parseError); }

const needsReview = !parseOk || !mathOk || confidence === null || confidence < 0.6;
const nameParts = String(meta.file_name || "file").split(".");
const ext = nameParts.length > 1 ? "." + nameParts.pop() : "";
const fileBase = safe(d.vendor_name) + "_" + (d.invoice_date || "no-date") + "_" + safe(d.invoice_number);

return {
  json: {
    vendor_name: d.vendor_name === undefined ? null : d.vendor_name,
    vendor_tax_id: d.vendor_tax_id === undefined ? null : d.vendor_tax_id,
    invoice_number: d.invoice_number === undefined ? null : d.invoice_number,
    invoice_date: d.invoice_date === undefined ? null : d.invoice_date,
    due_date: d.due_date === undefined ? null : d.due_date,
    currency: d.currency === undefined ? null : d.currency,
    line_items: Array.isArray(d.line_items) ? d.line_items : [],
    line_items_json: JSON.stringify(Array.isArray(d.line_items) ? d.line_items : []),
    subtotal: subtotal,
    tax_amount: taxAmount,
    tax_rate: num(d.tax_rate),
    total_amount: totalAmount,
    payment_terms: d.payment_terms === undefined ? null : d.payment_terms,
    confidence_score: confidence,
    parse_ok: parseOk,
    math_ok: mathOk,
    needs_review: needsReview,
    validation_note: notes.join("; "),
    attempt: 1,
    source_email: meta.source_email || "",
    email_subject: meta.email_subject || "",
    message_id: meta.message_id || "",
    file_name: meta.file_name || "",
    mime_type: meta.mime_type || "",
    file_kind: meta.file_kind || "",
    target_file_name: fileBase + ext,
    processed_at: new Date().toISOString(),
    raw_model_text: String(text).slice(0, 2000)
  },
  binary: src.binary
};

