// Builds a minimal, valid PDF from plain text lines. No libraries: a PDF is a text
// format, and a correct xref table is just byte offsets. Keep every string ASCII —
// the file is written as latin1, so "EUR" not the euro sign.
function buildPdf(lines) {
  function esc(s) {
    return String(s).split("\\").join("\\\\").split("(").join("\\(").split(")").join("\\)");
  }
  let content = "BT\n/F1 11 Tf\n50 800 Td\n14 TL\n";
  for (const line of lines) {
    content += "(" + esc(line) + ") Tj T*\n";
  }
  content += "ET";

  const objs = [
    null,
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    "<< /Length " + content.length + " >>\nstream\n" + content + "\nendstream",
  ];

  let pdf = "%PDF-1.4\n";
  const offsets = [];
  for (let i = 1; i <= 5; i++) {
    offsets[i] = pdf.length;
    pdf += i + " 0 obj\n" + objs[i] + "\nendobj\n";
  }
  const xrefStart = pdf.length;
  pdf += "xref\n0 6\n0000000000 65535 f \n";
  for (let i = 1; i <= 5; i++) {
    pdf += ("0000000000" + offsets[i]).slice(-10) + " 00000 n \n";
  }
  pdf += "trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n" + xrefStart + "\n%%EOF";

  return Buffer.from(pdf, "latin1").toString("base64");
}

function pdfItem(subject, body, fileName, lines) {
  return {
    json: { subject: subject, body: body, test_case: fileName },
    binary: {
      data: {
        data: buildPdf(lines),
        mimeType: "application/pdf",
        fileName: fileName,
        fileExtension: "pdf",
      },
    },
  };
}

// 1 - clean invoice, totals consistent. Expect: row logged, needs_review = false.
const clean = pdfItem(
  "Invoice INV-2026-001 from Acme Sh.p.k.",
  "Please find attached invoice INV-2026-001.",
  "test-1-clean-invoice.pdf",
  [
    "ACME SH.P.K.",
    "Rruga e Durresit 12, Tirane, Albania",
    "NIPT: L41234567A",
    "",
    "INVOICE",
    "Invoice Number: INV-2026-001",
    "Invoice Date: 12/03/2026",
    "Due Date: 11/04/2026",
    "",
    "Description                Qty   Unit Price     Amount",
    "Web development services     10       80.00     800.00",
    "Hosting, annual              1       200.00     200.00",
    "",
    "Subtotal:                                      1000.00 EUR",
    "VAT 20%:                                        200.00 EUR",
    "TOTAL:                                         1200.00 EUR",
    "",
    "Payment Terms: Net 30",
  ],
);

// 2 - totals do not add up (500 + 100 != 700). Expect: row logged, math_ok = false,
//     needs_review = true, review alert.
const badMath = pdfItem(
  "Invoice INV-2026-002 - Beta Consulting",
  "Attached is invoice INV-2026-002.",
  "test-2-bad-math.pdf",
  [
    "BETA CONSULTING LTD",
    "22 High Street, London, UK",
    "VAT: GB123456789",
    "",
    "INVOICE",
    "Invoice Number: INV-2026-002",
    "Invoice Date: 2026-03-15",
    "Due Date: 2026-04-15",
    "",
    "Description                Qty   Unit Price     Amount",
    "Strategy workshop            2       250.00     500.00",
    "",
    "Subtotal:                                       500.00 EUR",
    "VAT 20%:                                        100.00 EUR",
    "TOTAL:                                          700.00 EUR",
    "",
    "Payment Terms: Net 14",
  ],
);

// 3 - not an invoice at all. Expect: retry with the simplified prompt, then
//     Extraction Failed Alert. No row written.
const notInvoice = pdfItem(
  "Invoice discussion - meeting notes attached",
  "Notes from Tuesday, no invoice inside.",
  "test-3-not-an-invoice.pdf",
  [
    "MEETING NOTES - PRODUCT SYNC",
    "Tuesday, 10 March 2026",
    "",
    "Attendees: Ana, Blerim, Chris",
    "",
    "- Reviewed the onboarding funnel drop-off.",
    "- Agreed to postpone the pricing page redesign.",
    "- Chris to draft the Q2 roadmap by Friday.",
    "- No budget decisions were taken in this meeting.",
    "",
    "Next sync: 17 March 2026",
  ],
);

// 4 - unsupported attachment type. Expect: Unsupported File Alert, no Gemini call.
const unsupported = {
  json: {
    subject: "Fatura ne format teksti",
    body: "Fatura eshte bashkengjitur si skedar teksti.",
    test_case: "test-4-unsupported.txt",
  },
  binary: {
    data: {
      data: Buffer.from(
        "FATURE\nShitesi: Gamma SHPK\nNumri: INV-2026-004\nTotali: 300.00 EUR\n",
        "utf8",
      ).toString("base64"),
      mimeType: "text/plain",
      fileName: "test-4-unsupported.txt",
      fileExtension: "txt",
    },
  },
};

// 5 - barely legible receipt, most fields absent. Expect: low confidence_score,
//     needs_review = true.
const sparse = pdfItem(
  "Receipt from corner shop",
  "Small receipt attached.",
  "test-5-sparse-receipt.pdf",
  [
    "MINIMARKET",
    "",
    "bread        1.20",
    "milk         0.95",
    "",
    "TOTAL  2.15",
  ],
);

return [clean, badMath, notInvoice, unsupported, sparse];
